import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Tabs, Tab, Button, CircularProgress,
  Chip, Avatar, Divider, Grid, Card, CardContent, IconButton,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import EditIcon from '@mui/icons-material/Edit';
import PersonIcon from '@mui/icons-material/Person';
import WorkIcon from '@mui/icons-material/Work';
import DescriptionIcon from '@mui/icons-material/Description';
import ReceiptLongIcon from '@mui/icons-material/ReceiptLong';
import DeleteIcon from '@mui/icons-material/Delete';
import { useEmployee } from '../core/hooks/useEmployees';
import StatusBadge from '../core/components/ui/StatusBadge';
import BasicInfoTab from '../core/components/employee/BasicInfoTab';
import EmploymentTab from '../core/components/employee/EmploymentTab';
import DocumentsTab from '../core/components/employee/DocumentsTab';
import { toJalali } from '../core/utils/dateUtils';
import { formatPersianNumber, toPersianDigits } from '../core/utils/numberUtils';

const TYPE_COLORS = {
  leave: '#6366f1', absence: '#ef4444', benefit: '#10b981',
  salary: '#f59e0b', deduction: '#8b5cf6',
};

const TransactionsTab = ({ employeeId }) => {
  const queryClient = useQueryClient?.();
  const { t } = useTranslation();
  const { data, isLoading } = useQuery({
    queryKey: ['employee-transactions', employeeId],
    queryFn: () => axiosInstance.get(`/transactions/by_employee/?employee_id=${employeeId}`).then(r => r.data),
  });

  const items = Array.isArray(data) ? data : [];

  if (isLoading) return <Box sx={{ p: 4, textAlign: 'center' }}><CircularProgress size={24} /></Box>;

  if (!items.length) {
    return (
      <Box sx={{ p: 4, textAlign: 'center' }}>
        <ReceiptLongIcon sx={{ fontSize: 48, color: 'text.disabled', mb: 2 }} />
        <Typography color="textSecondary">تراکنشی برای این پرسنل ثبت نشده است</Typography>
      </Box>
    );
  }

  return (
    <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: 2 }}>
      <Table size="small">
        <TableHead>
          <TableRow>
            <TableCell sx={{ fontWeight: 700 }}>نوع</TableCell>
            <TableCell sx={{ fontWeight: 700 }}>عنوان</TableCell>
            <TableCell sx={{ fontWeight: 700 }}>مبلغ (ریال)</TableCell>
            <TableCell sx={{ fontWeight: 700 }}>مقدار</TableCell>
            <TableCell sx={{ fontWeight: 700 }}>تاریخ</TableCell>
            <TableCell width={50}></TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {items.map(tx => (
            <TableRow key={tx.id} hover>
              <TableCell>
                <Chip size="small" label={tx.transaction_type_display}
                  sx={{ color: TYPE_COLORS[tx.transaction_type], borderColor: TYPE_COLORS[tx.transaction_type], fontWeight: 500 }}
                  variant="outlined" />
              </TableCell>
              <TableCell>{tx.title || '—'}</TableCell>
              <TableCell>{tx.amount ? formatPersianNumber(tx.amount) : '—'}</TableCell>
              <TableCell>{tx.quantity ? formatPersianNumber(tx.quantity) : '—'}</TableCell>
              <TableCell>{toJalali(tx.date)}</TableCell>
              <TableCell>
                <IconButton size="small" color="error"
                  onClick={() => axiosInstance.delete(`/transactions/${tx.id}/`).then(() => {
                    if (queryClient) queryClient.invalidateQueries({ queryKey: ['employee-transactions', employeeId] });
                  })}>
                  <DeleteIcon fontSize="small" />
                </IconButton>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

const EmployeeProfilePage = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();
  const { data: employee, isLoading, error } = useEmployee(id);
  const [tabIndex, setTabIndex] = useState(0);

  if (isLoading) return <Box sx={{ textAlign: 'center', p: 8 }}><CircularProgress /></Box>;
  if (error || !employee) return (
    <Box sx={{ textAlign: 'center', p: 6 }}>
      <Typography color="error" variant="h5">{t('employees.not_found')}</Typography>
      <Button onClick={() => navigate('/employees')} sx={{ mt: 2 }}>{t('common.back')}</Button>
    </Box>
  );

  const e = employee;

  return (
    <Box>
      {/* Navigation */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/employees')}>{t('common.back')}</Button>
        <Button variant="contained" startIcon={<EditIcon />} onClick={() => navigate(`/employees/${id}/edit`)}>
          {t('common.edit')}
        </Button>
      </Box>

      {/* Hero Card - Glassmorphism */}
      <Paper sx={{ p: 4, mb: 3, position: 'relative', overflow: 'hidden' }}>
        <Box sx={{
          position: 'absolute', top: -60, left: -60, width: 200, height: 200,
          borderRadius: '50%', background: 'linear-gradient(135deg, rgba(99,102,241,0.15), rgba(236,72,153,0.1))',
          filter: 'blur(40px)',
        }} />
        <Box sx={{ position: 'relative', zIndex: 1 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 4, flexWrap: 'wrap' }}>
            <Avatar sx={{
              width: 88, height: 88, fontSize: 36, fontWeight: 800,
              background: 'linear-gradient(135deg, #6366f1, #ec4899)',
              boxShadow: '0 8px 32px rgba(99,102,241,0.3)',
            }}>
              {e.first_name?.charAt(0)}{e.last_name?.charAt(0)}
            </Avatar>
            <Box>
              <Typography variant="h4" fontWeight={800} sx={{ mb: 0.5 }}>{e.full_name}</Typography>
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Chip label={`${t('employees.employee_id')}: ${toPersianDigits(e.employee_id)}`} size="small" color="primary" variant="filled" />
                <Chip label={`${t('employees.national_id')}: ${toPersianDigits(e.national_id)}`} size="small" variant="outlined" />
                <StatusBadge status={e.status} size="medium" />
                <Typography variant="body2" color="textSecondary">
                  {e.department_detail?.name} — {e.job_title_detail?.name}
                </Typography>
              </Box>
            </Box>
          </Box>
        </Box>
      </Paper>

      {/* Quick Info Grid */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={6} md={3}>
          <Card variant="outlined" sx={{ background: 'rgba(255,255,255,0.5)', backdropFilter: 'blur(12px)' }}>
            <CardContent sx={{ p: 2, pb: '12px !important' }}>
              <Typography variant="caption" color="textSecondary">{t('employees.mobile')}</Typography>
              <Typography variant="body2" fontWeight={600}>{toPersianDigits(e.mobile)}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} md={3}>
          <Card variant="outlined" sx={{ background: 'rgba(255,255,255,0.5)', backdropFilter: 'blur(12px)' }}>
            <CardContent sx={{ p: 2, pb: '12px !important' }}>
              <Typography variant="caption" color="textSecondary">{t('employees.email')}</Typography>
              <Typography variant="body2" fontWeight={600}>{e.email || '—'}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} md={3}>
          <Card variant="outlined" sx={{ background: 'rgba(255,255,255,0.5)', backdropFilter: 'blur(12px)' }}>
            <CardContent sx={{ p: 2, pb: '12px !important' }}>
              <Typography variant="caption" color="textSecondary">{t('employees.hire_date')}</Typography>
              <Typography variant="body2" fontWeight={600}>{toJalali(e.hire_date)}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} md={3}>
          <Card variant="outlined" sx={{ background: 'rgba(255,255,255,0.5)', backdropFilter: 'blur(12px)' }}>
            <CardContent sx={{ p: 2, pb: '12px !important' }}>
              <Typography variant="caption" color="textSecondary">{t('employees.work_location')}</Typography>
              <Typography variant="body2" fontWeight={600}>{e.work_location_detail?.name || '—'}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabs */}
      <Paper>
        <Tabs
          value={tabIndex}
          onChange={(ev, v) => setTabIndex(v)}
          variant="fullWidth"
          sx={{ borderBottom: 1, borderColor: 'divider', px: 2 }}
        >
          <Tab icon={<PersonIcon />} label={t('employees.basic_info')} iconPosition="start" />
          <Tab icon={<WorkIcon />} label={t('employees.employment_info')} iconPosition="start" />
          <Tab icon={<ReceiptLongIcon />} label="تراکنش‌ها" iconPosition="start" />
          <Tab icon={<DescriptionIcon />} label={t('documents.title')} iconPosition="start" />
        </Tabs>
        <Box sx={{ p: 3 }}>
          {tabIndex === 0 && <BasicInfoTab employee={e} />}
          {tabIndex === 1 && <EmploymentTab employee={e} />}
          {tabIndex === 2 && <TransactionsTab employeeId={e.id} />}
          {tabIndex === 3 && <DocumentsTab employeeId={e.id} />}
        </Box>
      </Paper>
    </Box>
  );
};

export default EmployeeProfilePage;
